  "prediction_basis_card_ids": [
    "C04", "C07", "C28", "C16", "C24", "C25", "C22", "C17"
  ],
  "claims": [
    {
      "claim": "Small polar polyhydroxy compounds with physicochemical profiles comparable to ascorbic acid show oral bioavailability at or above the 20% threshold: mannitol 63% in healthy adults and ~20-24% in patients, sorbitol 36-38%, glucose 38-84%, and propylene glycol very high.",
      "card_ids": ["C04", "C02", "C06", "C10", "C11", "C12", "C15", "C20", "C26", "C32", "C07", "C28", "C16", "C24", "C25", "C22"]
    },
    {
      "claim": "Additional polar or small-molecule contexts also support F >=20%: topiramate >80%, frusemide ~40%, gallium maltolate 25-57%, pipemidic acid 93%, and diflunisal 89.5%, although structural transferability is lower for some of these.",
      "card_ids": ["C17", "C09", "C03", "C14", "C23", "C31", "C18"]
    },
    {
      "claim": "The only coherent low-F context, gemcitabine (10%, poor/low), is attributed to first-pass metabolism by cytidine deaminase and is not transferable to ascorbic acid, which lacks that metabolic liability.",
      "card_ids": ["C01", "C05", "C13", "C19", "C21", "C27", "C29", "C30"]
    },
    {
      "claim": "The physicochemical prior's unfavorable passive permeability is an uncertain prior, and its own caveat notes that active transport (SVCT1/2) could significantly enhance ascorbic acid absorption; the empirical pattern of high F in polar small molecules supports F >=20%.",
      "card_ids": ["C04", "C07", "C16", "C22"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C04", "C07", "C16", "C22", "C17", "C01", "C13", "C27", "C30"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ascorbic acid is present in the supplied cards; all support is transfer-based.",
    "Mannitol data at high colonoscopy doses are borderline (~20-24%) and may be dose- or patient-dependent.",
    "Active transport (SVCT1/2) and dose-dependent absorption of ascorbic acid are not directly measured in the cited records.",
    "The frusemide context card's canonical SMILES does not match the named drug, reducing confidence in that card's transferability."
  ],
  "decision_summary": "Prediction high: L1 evidence from structurally related small polar polyhydroxy compounds (mannitol, sorbitol, glucose, propylene glycol) shows oral bioavailability at or above 20%, and the only low-F context (gemcitabine) is explained by a first-pass metabolism mechanism not applicable to ascorbic acid. The physicochemical prior is uncertain and does not outweigh this empirical pattern."
}

